import{z as i,x as n,o as t,c as d,q as o,j as s,D as r,d as E,s as l,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"中断线程化","description":"","frontmatter":{"title":"中断线程化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/irq-thread.md","filePath":"cs/irq-thread.md","lastUpdated":1791413859000}'),p={name:"cs/irq-thread.md"};function m(h,a,D,u,c,f){const A=n("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="中断线程化" tabindex="-1">中断线程化 <a class="header-anchor" href="#中断线程化" aria-label="Permalink to &quot;中断线程化&quot;">​</a></h1><div class="epigraph"><p>把 IRQ 处理做成可调度的内核线程，延迟变成调度问题，于是可以用优先级对抗共享锁上的反转。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 对中断处理的整理</footer></div><p><a href="/cs/tasklet-workqueue">上一课</a>把可睡工作丢给 kworker，但硬 IRQ 与 tasklet 仍在中断/软中断上下文，优先级不归调度器管。实时路径上，一次长 tasklet 可以挡住高优先级线程。<a href="/cs/realtime-sched">实时调度对照</a>将警告 ISR 会拉长最坏执行。缺口是：让该 IRQ 的下半（甚至大部分处理）跑在<strong>专门的中断线程</strong>里，用调度策略而不是关中断来排队。本课只钉这个模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软中断在返回路径上跑，等于临时继承了被打断线程的上下文，却没有自己的调度实体。线程化：上半部仍极短（应答、唤醒 IRQ 线程），其余在 <code>irq/n-foo</code> 一类内核线程中执行，可睡、可被设为实时优先级。缺口不是新的 PIC 硬件，而是把「谁在处理这条 IRQ」变成调度器看见的线程。</p><p><span class="marginnote">术语翻译：<code>irq/n-foo</code> 就是「第 n 号中断、名叫 foo 的专属处理线程」——每条被线程化的 IRQ 在 <code>ps</code> 里都能看到这样一个内核线程，它能睡、能被抢占、有自己的优先级。</span></p><p><span class="marginnote">主线上半部仍不能睡。线程化降低的是<strong>处理函数主体</strong>的上下文，不是取消硬中断入口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册 IRQ 时声明 threaded：内核创建或复用处理线程。硬中断：清设备或仅屏蔽，然后唤醒该线程。线程：抢到 CPU 后跑处理函数，必要时再开中断。多个 IRQ 可各有线程，优先级按设备紧迫性配置——配置细节是运维，主干只要求存在独立调度实体。</p>',9)),(t(),s(B,null,{default:r(()=>[l(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E7%A1%AC%20IRQ%20%E7%9F%AD%E4%B8%8A%E5%8D%8A%22%5D%20--%3E%20WAKE%5B%22%E5%94%A4%E9%86%92%20IRQ%20%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20WAKE%20--%3E%20THR%5B%22%E7%BA%BF%E7%A8%8B%E4%B8%8A%E4%B8%8B%E6%96%87%3A%20%E5%8F%AF%E7%9D%A1%E5%A4%84%E7%90%86%22%5D%0A%20%20THR%20--%3E%20USER%5B%22%E5%94%A4%E9%86%92%E7%94%A8%E6%88%B7%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 workqueue 的差别：IRQ 线程绑定这条中断的生命周期与默认优先级，而不是通用工人池。两者可叠加。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("线程化把中断延迟从「关中断时长」改写成「IRQ 线程何时被选中」。于是"),e("a",{href:"/cs/scheduling-metrics"},"调度指标"),E("与实时队列可以直接作用在处理路径上。代价是多一次唤醒与切换；对高频网卡可能不划算，对慢速设备与实时外设划算。共享数据仍要锁；但持锁者是线程，可以用睡眠锁，只要上半部不碰同一把睡眠锁。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：非线程化的软中断像结账时硬要「加塞」的顾客，谁也拦不住；线程化之后它变成普通排队者，调度员（调度器）随时可以请它让位给更急的人。")],-1)),a[7]||(a[7]=e("p",null,"高优先级线程到达时，两条路径的差别：",-1)),(t(),s(B,null,{default:r(()=>[l(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E5%AE%9E%E6%97%B6%E7%BA%BF%E7%A8%8B%E5%B0%B1%E7%BB%AA%22%5D%20--%3E%7C%22%E9%9D%9E%E7%BA%BF%E7%A8%8B%E5%8C%96%EF%BC%9A%E8%BD%AF%E4%B8%AD%E6%96%AD%E6%AD%A3%E5%9C%A8%E8%B7%91%22%7C%20WAIT%5B%22%E5%8F%AA%E8%83%BD%E7%AD%89%E8%BD%AF%E4%B8%AD%E6%96%AD%E8%B7%91%E5%AE%8C%EF%BC%8C%E5%BB%B6%E8%BF%9F%E4%B8%8D%E5%8F%AF%E6%8E%A7%22%5D%0A%20%20H%20--%3E%7C%22%E7%BA%BF%E7%A8%8B%E5%8C%96%EF%BC%9AIRQ%20%E7%BA%BF%E7%A8%8B%E5%8F%AF%E8%A2%AB%E6%8A%A2%E5%8D%A0%22%7C%20PRE%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E7%AB%8B%E5%8D%B3%E6%8D%A2%E5%85%A5%E5%AE%9E%E6%97%B6%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20PRE%20--%3E%20RT%5B%22%E5%BB%B6%E8%BF%9F%E7%94%B1%E4%BC%98%E5%85%88%E7%BA%A7%E5%86%B3%E5%AE%9A%EF%BC%8C%E5%8F%AF%E4%B8%8A%E7%95%8C%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每块驱动是否 threadirqs 的 Kconfig 写完，不保证桌面发行版默认全部线程化。优先级反转若锁在 IRQ 线程与用户实时线程之间，完整协议在调度课。也不把用户进程当成 IRQ 线程来跑驱动。</p><p><span class="marginnote">常见误区：初学者容易以为线程化后硬中断「没了」。实际上每次中断仍要进一次极短的硬上半（应答设备、唤醒线程），被消掉的是长处理主体「不可调度」这件事。</span></p><p>后课默认：IRQ 处理可以是可调度线程。多核上这条 IRQ 该送到哪颗 CPU，下一课讲中断亲和。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线程化 IRQ：短硬上半 + 可调度处理线程。</li><li>延迟变成调度问题；高频路径未必适合。</li><li>送到哪颗核是下一课亲和。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',6))])}const R=i(p,[["render",m]]);export{F as __pageData,R as default};
